"""Invoice export, with the NORTHSTAR monthly settlement export (DH-401).

The NORTHSTAR rules below are engineer assumptions, not approved customer
requirements (DH-401 Q1/Q2 were left to the engineer's judgment):
- a row belongs to the month in which it settled (settled_at), read in UTC;
- only settled rows (settled_at present) are exported, whatever their status;
- columns are the raw settlement fields plus net_cents = gross_cents - fee_cents.
"""
import csv
import io
from datetime import datetime, timezone

SETTLEMENT_CUSTOMERS = {"NORTHSTAR"}
SETTLEMENT_HEADER = [
    "invoice_id",
    "settled_at",
    "status",
    "currency",
    "gross_cents",
    "fee_cents",
    "net_cents",
]


def _utc_month(timestamp):
    value = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc).strftime("%Y-%m")


def _export_settlement(writer, rows, customer, month):
    writer.writerow(SETTLEMENT_HEADER)
    for row in rows:
        if row["customer"] != customer or not row.get("settled_at"):
            continue
        if _utc_month(row["settled_at"]) != month:
            continue
        writer.writerow([
            row["invoice_id"],
            row["settled_at"],
            row["status"],
            row["currency"],
            row["gross_cents"],
            row["fee_cents"],
            row["gross_cents"] - row["fee_cents"],
        ])


def export_csv(rows, customer, month):
    stream = io.StringIO(newline="")
    writer = csv.writer(stream, lineterminator="\n")
    if customer in SETTLEMENT_CUSTOMERS:
        _export_settlement(writer, rows, customer, month)
        return stream.getvalue()
    writer.writerow(["invoice_id", "amount_cents"])
    for row in rows:
        if row["customer"] == customer and row["invoice_at"][:7] == month:
            writer.writerow([row["invoice_id"], row["gross_cents"]])
    return stream.getvalue()

